local e=''
local c=''
assert(type(crypt)=='table'and type(crypt.decrypt)=='function'and type(crypt.hash)=='function','Fortuna: executor crypt.decrypt and crypt.hash required')
local decode=crypt.base64decode or(type(crypt.base64)=='table'and crypt.base64.decode)
assert(type(decode)=='function','Fortuna: base64 decoder unavailable')
local d=string.split(decode(e),'\n')
assert(#d==6,'Fortuna: invalid encrypted envelope')
local function digest(value)
    local hex=crypt.hash(value,'sha256')
    assert(type(hex)=='string'and #hex==64 and hex:match('^%x+$'),'Fortuna: invalid SHA-256 response')
    return hex:lower()
end
local function rawDigest(value)
    return(digest(value):gsub('%x%x',function(pair)return string.char(tonumber(pair,16))end))
end
local function mac(key,value)
    if #key>64 then key=rawDigest(key)end
    key=key..string.rep('\0',64-#key)
    local inner,outer={},{}
    for index=1,64 do
        local byte=key:byte(index)
        inner[index]=string.char(bit32.bxor(byte,0x36));outer[index]=string.char(bit32.bxor(byte,0x5c))
    end
    return digest(table.concat(outer)..rawDigest(table.concat(inner)..value))
end
local authenticated=d[2]..'\n'..d[5]..'\n'..d[6]..'\n'..c
local actual=mac(decode(d[3]),authenticated)
local difference=0
for index=1,64 do difference=bit32.bor(difference,bit32.bxor(actual:byte(index),d[4]:byte(index)or 0))end
assert(#d[4]==64 and difference==0,'Fortuna: encrypted payload integrity check failed')
local ok,plain=pcall(crypt.decrypt,c,d[1],d[2],'CBC')
assert(ok and type(plain)=='string','Fortuna: AES decryption failed')
assert(#plain==tonumber(d[6])and digest(plain)==d[5],'Fortuna: decrypted build identity mismatch')
local entry,compileError=loadstring(plain,'Fortuna encrypted release')
assert(entry,compileError)
return entry()
